1	// Pricing helpers for checkout.
2	
3	const RATES = {
4	  // Null prototype: the table is a pure lookup and never inherits Object
5	  // members, so an unknown code always misses.
6	  __proto__: null,
7	  SAVE10: 0.1,
8	  SAVE20: 0.2,
9	  HALFOFF: 0.5,
10	};
11	
12	// Returns the discount rate for a code. BUG: an unrecognized code is not in
13	// RATES, so this returns undefined instead of "no discount".
14	function getDiscountRate(code) {
15	  return RATES[code];
16	}
17	
18	// Returns the price after applying the discount for `code`.
19	function finalPrice(price, code) {
20	  const rate = getDiscountRate(code);
21	  return price - price * rate;
22	}
23	
24	module.exports = { getDiscountRate, finalPrice };
